package com.oms.order.service;

import com.ruoyi.common.core.constant.SecurityConstants;
import com.ruoyi.common.core.domain.R;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.time.LocalDateTime;
import java.util.*;
import static com.oms.order.service.OrderValues.*;

/** WMS receipt -> stable inventory command -> atomic local shipment/parcel confirmation. */
@Service
public class OrderShipmentReceiptService {
    @Resource private OrderRepository repository;
    @Resource private OrderShipmentDispatchService locks;
    @Resource private OrderShipmentWmsClient wms;
    @Resource private OrderWarehouseClient inventory;
    private TransactionTemplate tx(){TransactionTemplate t=new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));t.setTimeout(120);return t;}
    private Object canonical(Object value){if(value instanceof Map){Map<String,Object> copy=new TreeMap<>();((Map<?,?>)value).forEach((k,v)->copy.put(k.toString(),canonical(v)));return copy;}if(value instanceof List){List<Object> copy=new ArrayList<>();for(Object item:(List<?>)value)copy.add(canonical(item));return copy;}return value;}
    private String error(RuntimeException e){String message=e instanceof IllegalArgumentException?e.getMessage():"出库记账结果暂未确认，请按原回传核对";if(message==null)message="出库记账结果暂未确认";return message.substring(0,Math.min(1000,message.length()));}
    private Map<String,Object> result(long id,String state,String message){Map<String,Object> r=new LinkedHashMap<>();r.put("id",id);r.put("state",state);r.put("success","COMPLETED".equals(state));r.put("message",message);return r;}
    @SuppressWarnings("unchecked") private Map<String,Object> prepare(String company,Map<String,Object> shipment,Map<String,Object> event,String actor){
        require(event.get("payload") instanceof Map,"仓库回传快照缺失");Map<String,Object> receipt=(Map<String,Object>)event.get("payload");long remote=number(event,"id");require(remote>0&&number(receipt,"shipment_id")==number(shipment,"id")&&text(receipt,"shipment_sn").equals(text(shipment,"shipment_sn")),"出库回传不属于该发货单");List<Map<String,Object>> intents=repository.db().query("SELECT * FROM oms_order_shipment_dispatch WHERE company_code=? AND shipment_id=? FOR UPDATE",ROW,company,shipment.get("id"));require(intents.size()==1,"发货单尚无WMS下发记录");Map<String,Object> intent=intents.get(0);require(text(intent,"payload_hash").equals(text(receipt,"original_payload_hash"))&&(intent.get("remote_task_id")==null||number(intent,"remote_task_id")==number(receipt,"task_id")),"出库回传与原下发任务或快照不一致");require(!"CANCELED".equals(text(intent,"state"))&&!Arrays.asList("VOIDING","VOIDED").contains(text(shipment,"status")),"原履约单据已停止，请核对仓库实际执行结果");require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_virtual_outbound WHERE company_code=? AND shipment_id=?",Long.class,company,shipment.get("id"))==0,"虚拟出库单不能接收WMS出库回传");Map<String,Object> original;try{original=JSON.readValue(text(intent,"payload_json"),Map.class);}catch(Exception e){throw new IllegalArgumentException("原下发快照损坏");}Map<String,Object> route=(Map<String,Object>)original.get("route");require(text(route,"external_warehouse").equals(text(receipt,"external_warehouse"))&&text(route,"external_owner").equals(text(receipt,"external_owner"))&&!text(receipt,"external_order").isEmpty()&&(text(intent,"external_order").isEmpty()||text(intent,"external_order").equals(text(receipt,"external_order"))),"回传仓库、货主或外部单号与原绑定不一致");String request="WO"+hash(company+"/"+text(shipment,"shipment_sn")+"/"+remote).substring(0,40),receiptHash=hash(encode(canonical(receipt)));List<Map<String,Object>> old=repository.db().query("SELECT * FROM oms_order_shipment_outbound WHERE company_code=? AND request_id=? FOR UPDATE",ROW,company,request);if(!old.isEmpty()){Map<String,Object> task=old.get(0),p=decode(task);require(receiptHash.equals(text(p,"receipt_hash")),"同一出库回传事件的内容发生变化");return task;}
        require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_outbound WHERE company_code=? AND shipment_id=? AND source_mode='WMS' AND state<>'COMPLETED'",Long.class,company,shipment.get("id"))==0,"该发货单仍有前次出库记账待核对，请先处理原回传");require(receipt.get("lines") instanceof List&&receipt.get("packages") instanceof List,"出库回传缺少商品或包裹信息");List<?> reported=(List<?>)receipt.get("lines");require(reported.size()<=500&&((List<?>)receipt.get("packages")).size()<=100,"出库回传明细超过限制");Map<Long,Map<String,Object>> plans=new HashMap<>();for(Map<String,Object> line:(List<Map<String,Object>>)original.get("lines"))plans.put(number(line,"id"),line);Set<Long> seen=new HashSet<>();List<Map<String,Object>> lines=new ArrayList<>();long total=0;
        for(Object raw:reported){require(raw instanceof Map,"出库回传行无效");Map<String,Object> r=(Map<String,Object>)raw,plan=plans.get(number(r,"id"));require(plan!=null&&seen.add(number(r,"id"))&&number(r,"quantity")>0&&text(plan,"sku_sn").equals(text(r,"sku_sn"))&&text(plan,"batch_code").equals(text(r,"batch_code")),"回传商品、行号或批次与原下发不一致");Map<String,Object> line=repository.db().query("SELECT * FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=? AND id=? FOR UPDATE",ROW,company,shipment.get("id"),r.get("id")).stream().findFirst().orElseThrow(()->new IllegalArgumentException("原发货行缺失"));for(String key:Arrays.asList("sku_sn","platform_oid","store_code"))require(text(plan,key).equals(text(line,key)),"原发货行来源发生变化");require(number(plan,"quantity")==number(line,"quantity")&&number(r,"quantity")<=number(line,"quantity")-number(line,"shipped_quantity"),"累计回传出库超过发货行剩余数量");Map<String,Object> out=new LinkedHashMap<>();for(String field:Arrays.asList("id","allocation_id","sku_sn","platform_oid","store_code","source_type","batch_id","stock_source_id"))out.put(field,line.get(field));out.put("owner_code",shipment.get("owner_code"));out.put("real_store_code",shipment.get("real_store_code"));out.put("outbound_before",line.get("shipped_quantity"));out.put("quantity",r.get("quantity"));lines.add(out);total+=number(r,"quantity");}
        require(total==number(receipt,"quantity")&&(total>0||number(receipt,"final_confirmation")==1||reported.isEmpty()),"回传汇总数量不一致");List<Map<String,Object>> packs=new ArrayList<>();Map<Long,Long> packaged=new HashMap<>();OrderShipmentOutboundRecords records=new OrderShipmentOutboundRecords(repository);for(Object raw:(List<?>)receipt.get("packages")){require(raw instanceof Map,"回传包裹无效");Map<String,Object> source=(Map<String,Object>)raw,pack=new LinkedHashMap<>(source);pack.putAll(records.warehouseCarrier(company,shipment,text(source,"warehouse_carrier_code")));pack.put("outbound_time",text(receipt,"outbound_time"));require(pack.get("lines") instanceof List&&!((List<?>)pack.get("lines")).isEmpty(),"包裹来源行缺失");for(Object item:(List<?>)pack.get("lines")){require(item instanceof Map,"包裹来源行无效");Map<String,Object> l=(Map<String,Object>)item;require(seen.contains(number(l,"id"))&&number(l,"quantity")>0&&text(plans.get(number(l,"id")),"sku_sn").equals(text(l,"sku_sn")),"包裹商品与回传行不一致");packaged.merge(number(l,"id"),number(l,"quantity"),Math::addExact);}packs.add(pack);}require(packaged.size()==lines.size(),"包裹尚未覆盖本次出库行");for(Map<String,Object> line:lines)require(packaged.get(number(line,"id"))==number(line,"quantity"),"包裹与出库行数量不一致");
        packs.sort(Comparator.comparing(p->text(p,"carrier_code")+"/"+text(p,"express_code")));for(Map<String,Object> pack:packs)records.checkWaybill(company,shipment,pack,"WMS");
        Map<String,Object> p=new LinkedHashMap<>();p.put("request_id",request);p.put("shipment_sn",shipment.get("shipment_sn"));p.put("channel_id",shipment.get("channel_id"));p.put("platform_tid",shipment.get("platform_tid"));p.put("quantity",total);p.put("source_mode","WMS");p.put("operator_name","仓库出库回传");p.put("lines",lines);p.put("packages",packs);p.put("receipt_hash",receiptHash);String json=encode(canonical(p));require(json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=900000,"出库快照超过限制");repository.db().update("INSERT INTO oms_order_shipment_outbound(company_code,shipment_id,shipment_sn,request_id,source_mode,remote_event_id,message_id,final_confirmation,outbound_time,quantity,payload_json,payload_hash,created_by) VALUES (?,?,?,?,'WMS',?,?,?,?,?,?,?,?)",company,shipment.get("id"),shipment.get("shipment_sn"),request,remote,text(receipt,"message_id"),number(receipt,"final_confirmation"),text(receipt,"outbound_time").isEmpty()?null:time(text(receipt,"outbound_time")).format(TIME),total,json,hash(json),actor);repository.db().update("UPDATE oms_order_shipment_dispatch SET state='ACCEPTED',remote_task_id=?,external_order=?,warehouse_status=?,last_error='' WHERE company_code=? AND shipment_id=?",receipt.get("task_id"),receipt.get("external_order"),receipt.get("warehouse_status"),company,shipment.get("id"));return repository.db().query("SELECT * FROM oms_order_shipment_outbound WHERE company_code=? AND request_id=?",ROW,company,request).get(0);
    }
    @SuppressWarnings("unchecked") private Map<String,Object> decode(Map<String,Object> task){require(hash(text(task,"payload_json")).equals(text(task,"payload_hash")),"出库指令快照校验失败");try{return JSON.readValue(text(task,"payload_json"),Map.class);}catch(Exception e){throw new IllegalArgumentException("出库指令快照无法解析");}}
    @SuppressWarnings("unchecked") public Map<String,Object> process(String company,Map<String,Object> event,boolean retry,String actor){require(event.get("payload") instanceof Map,"出库事件参数无效");Map<String,Object> receipt=(Map<String,Object>)event.get("payload");long shipmentId=number(receipt,"shipment_id");Map<String,Object> result=tx().execute(s->{Map<String,Object> shipment=locks.lock(company,shipmentId,null,false),task=prepare(company,shipment,event,actor);if("COMPLETED".equals(text(task,"state")))return result(number(task,"id"),"COMPLETED","原出库回传已记账，未重复扣减");if("FAILED".equals(text(task,"state"))&&!retry)return result(number(task,"id"),"FAILED",text(task,"last_error"));if(!retry&&task.get("next_attempt")!=null&&time(text(task,"next_attempt")).isAfter(LocalDateTime.now()))return result(number(task,"id"),"PENDING","原出库记账等待再次核对");try{Map<String,Object> command=decode(task),reply;
            if(number(task,"quantity")==0){reply=new LinkedHashMap<>();reply.put("state","COMPLETED");reply.put("source_mode","WMS");reply.put("request_id",task.get("request_id"));reply.put("shipment_sn",shipment.get("shipment_sn"));reply.put("quantity",0);reply.put("lines",Collections.emptyList());}else{reply=data(inventory.warehouseReceipt(company,text(task,"request_id"),SecurityConstants.INNER));if(!"COMPLETED".equals(text(reply,"state"))){require("MISSING".equals(text(reply,"state")),"库存出库回执状态不明确");repository.db().update("UPDATE oms_order_shipment_outbound SET attempts=attempts+1 WHERE company_code=? AND id=?",company,task.get("id"));R<Map<String,Object>> response=inventory.warehouseOutbound(company,command,SecurityConstants.INNER);if(response!=null&&!R.isSuccess(response)){String message=error(new IllegalArgumentException(response.getMsg()));repository.db().update("UPDATE oms_order_shipment_outbound SET state='FAILED',last_error=? WHERE company_code=? AND id=?",message,company,task.get("id"));return result(number(task,"id"),"FAILED",message);}reply=data(response);}}
            TransactionTemplate nested=tx();nested.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_NESTED);Map<String,Object> confirmed=reply;nested.execute(st->{apply(company,shipment,task,command,confirmed,actor);return null;});return result(number(task,"id"),"COMPLETED","出库回传已确认，库存、发货数量和包裹已更新");
        }catch(RuntimeException e){String message=error(e);repository.db().update("UPDATE oms_order_shipment_outbound SET state='UNKNOWN',last_error=?,next_attempt=DATE_ADD(NOW(),INTERVAL 30 SECOND) WHERE company_code=? AND id=?",message,company,task.get("id"));return result(number(task,"id"),"UNKNOWN",message);}});
        if(Arrays.asList("COMPLETED","FAILED").contains(text(result,"state")))try{Map<String,Object> body=new LinkedHashMap<>();body.put("success","COMPLETED".equals(text(result,"state")));body.put("message",text(result,"message"));R<Boolean> response=wms.receiptResult(company,number(event,"id"),body,SecurityConstants.INNER);require(response!=null&&R.isSuccess(response)&&Boolean.TRUE.equals(response.getData()),"回传记账结果尚未同步仓库对接侧");}catch(RuntimeException e){result.put("ack_pending",true);}return result;
    }
    @SuppressWarnings("unchecked") private void apply(String company,Map<String,Object> shipment,Map<String,Object> task,Map<String,Object> command,Map<String,Object> reply,String actor){require("COMPLETED".equals(text(reply,"state"))&&"WMS".equals(text(reply,"source_mode"))&&text(reply,"request_id").equals(text(task,"request_id"))&&text(reply,"shipment_sn").equals(text(shipment,"shipment_sn"))&&number(reply,"quantity")==number(task,"quantity"),"库存出库回执身份或数量不一致");require(reply.get("lines") instanceof List,"库存出库行回执缺失");Map<Long,Map<String,Object>> expected=new HashMap<>();for(Map<String,Object> line:(List<Map<String,Object>>)command.get("lines"))expected.put(number(line,"id"),line);Set<Long> seen=new HashSet<>();for(Object raw:(List<?>)reply.get("lines")){require(raw instanceof Map,"库存出库行无效");Map<String,Object> l=(Map<String,Object>)raw,old=expected.get(number(l,"id"));require(old!=null&&seen.add(number(l,"id")),"库存回执行重复或不属于原指令");for(String f:Arrays.asList("sku_sn","platform_oid","store_code","owner_code","real_store_code","source_type"))require(text(old,f).equals(text(l,f)),"库存出库回执来源身份不一致");for(String f:Arrays.asList("allocation_id","batch_id","stock_source_id","quantity","outbound_before"))require(number(old,f)==number(l,f),"库存出库回执来源或数量不一致");require(number(l,"outbound_quantity")==number(old,"outbound_before")+number(old,"quantity"),"库存累计出库数量不一致");require(repository.db().update("UPDATE oms_order_shipment_line SET shipped_quantity=? WHERE company_code=? AND shipment_id=? AND id=? AND shipped_quantity=? AND quantity>=?",l.get("outbound_quantity"),company,shipment.get("id"),l.get("id"),old.get("outbound_before"),l.get("outbound_quantity"))==1,"发货行累计出库进度已变化");}require(seen.size()==expected.size(),"库存出库回执行不完整");OrderShipmentOutboundRecords records=new OrderShipmentOutboundRecords(repository);for(Map<String,Object> pack:(List<Map<String,Object>>)command.get("packages"))records.packageRecord(company,shipment,number(task,"id"),pack,"WMS","WP"+hash(text(task,"request_id")+"/"+text(pack,"package_code")).substring(0,40),actor);long shipped=repository.db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND shipment_id=?",Long.class,company,shipment.get("id"));require(shipped<=number(shipment,"quantity"),"累计出库超过发货单数量");repository.db().update("UPDATE oms_order_shipment SET status=?,control_version=control_version+1 WHERE company_code=? AND id=?",shipped==number(shipment,"quantity")?"SHIPPED":shipped>0?"PART_SHIPPED":"WAREHOUSE_PROCESSING",company,shipment.get("id"));repository.db().update("UPDATE oms_order_shipment_outbound SET state='COMPLETED',last_error='',completed_at=NOW() WHERE company_code=? AND id=?",company,task.get("id"));repository.db().update("UPDATE oms_order SET control_version=control_version+1 WHERE company_code=? AND id=?",company,shipment.get("order_id"));String message="仓库出库确认 "+task.get("quantity")+" 件，累计已出库 "+shipped+" 件"+(number(task,"final_confirmation")==1&&shipped<number(shipment,"quantity")?"；仓库最终确认仍有未出库余量，请核对履约异常":"");repository.db().update("INSERT INTO oms_order_shipment_log(company_code,shipment_id,action,result,message,operator_name) VALUES (?,?,'WMS_OUTBOUND_RESULT','SUCCESS',?,?)",company,shipment.get("id"),message,actor);repository.log(company,number(shipment,"platform_order_id"),"WMS_OUTBOUND_RESULT","SUCCESS",text(shipment,"shipment_sn")+"："+message,actor);repository.shipmentChanged(company,number(shipment,"id"));}
    public Map<String,Object> ready(String company,long eventId){Map<String,Object> event=data(wms.receiptEvent(company,eventId,SecurityConstants.INNER));
        if(!"PENDING".equals(text(event,"post_state")))return result(eventId,"SKIPPED","原事件已处理或需要人工重试，未重新记账");return process(company,event,false,"出库回传即时记账");
    }
    @SuppressWarnings("unchecked") public Map<String,Object> pollCompany(String company){
        com.oms.common.task.ScanReport report=new com.oms.common.task.ScanReport();Map<String,Object> batch=data(wms.receiptScan(company,SecurityConstants.INNER));report.add("review_pending",number(batch,"review_pending"));for(Map<String,Object> review:(List<Map<String,Object>>)batch.getOrDefault("reviews",Collections.emptyList()))report.note(company,number(review,"shipment_id"),text(review,"shipment_sn"),"WAIT_REVIEW","原回传被拒绝，待人工核对，本次未扣账");
        for(Map<String,Object> event:(List<Map<String,Object>>)batch.get("events")){
            Map<String,Object> payload=(Map<String,Object>)event.get("payload");String state="FAILED";
            try{Map<String,Object> result=process(company,event,false,"出库回传任务");state="COMPLETED".equals(text(result,"state"))?"SUCCESS":text(result,"state");}catch(RuntimeException e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Outbound receipt requires review company={} event={}",company,event.get("id"));}
            report.record(company,number(payload,"shipment_id"),text(event,"shipment_sn"),state,"SUCCESS".equals(state)?"原出库回传已记账":"请核对原回传；不绕过人工核对或重复扣账");
        }return report;
    }
    public List<Map<String,Object>> reconcile(String company,long id,String actor){Map<String,Object> shipment=repository.db().query("SELECT id,shipment_sn FROM oms_order_shipment WHERE company_code=? AND id=?",ROW,company,id).stream().findFirst().orElseThrow(()->new IllegalArgumentException("发货单不存在或无权访问"));List<Map<String,Object>> results=new ArrayList<>();for(Map<String,Object> event:data(wms.receipts(company,text(shipment,"shipment_sn"),true,SecurityConstants.INNER)))try{results.add(process(company,event,true,actor));}catch(RuntimeException e){results.add(result(number(event,"id"),"FAILED",error(e)));}long pending=data(wms.reviews(company,id,SecurityConstants.INNER)).stream().filter(r->"WAIT_REVIEW".equals(text(r,"state"))).count();if(pending>0)results.add(result(id,"WAIT_REVIEW","有 "+pending+" 条仓库回传被拒绝，待人工核对；这些回传尚未扣账，请在“仓库回传核对”中处理"));if(results.isEmpty())results.add(result(id,"PENDING","仓库暂无待记账或待人工核对的出库回传；本次不会创建出库记录或扣减库存"));return results;}
}
